window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[303]={"id":"303","numero":303,"titre":"Tumeurs de l'estomac","objectifs":[{"id":"303-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des tumeurs de l’estomac","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">tumeurs de l’estomac</span> regroupent l’ensemble des proliférations bénignes ou malignes développées aux dépens de la paroi gastrique. L’<span class=\"kw-def\">adénocarcinome gastrique</span> représente à lui seul <span class=\"kw-chiffre\">95 %</span> des tumeurs malignes — toute autre <span class=\"kw-bio\">histologie</span> reste rare mais doit être systématiquement recherchée si le tableau est atypique.</p>\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Entités principales</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeurs bénignes</strong> (<span class=\"kw-clinique\">les</span> plus fréquentes)</td>\n            <td>\n              <strong>Polype hyperplasique :</strong> antre ;<br>\n              <strong>Polype glandulokystique :</strong> fundus, associé aux <span class=\"kw-ttt\">IPP</span> au long cours ;<br>\n              <strong>Polype adénomateux :</strong> <span class=\"kw-clinique\">lésion</span> précancéreuse ;<br>\n              <strong><span class=\"kw-clinique\">Gastrite</span> à gros plis de Ménétrier :</strong> exceptionnelle.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tumeurs malignes</strong> (par ordre de fréquence)</td>\n            <td>\n              <strong><span class=\"kw-def\">Adénocarcinome</span> :</strong> <span class=\"kw-chiffre\">95 %</span> ;<br>\n              <strong>Lymphome de MALT à petites cellules :</strong> bas <span class=\"kw-def\">grade</span>, lié à <span class=\"kw-clinique\">HP</span> ;<br>\n              <strong>Lymphome à grandes cellules :</strong> haut grade ;<br>\n              <strong>GIST :</strong> tumeur mésenchymateuse (cellules de Cajal) ;<br>\n              <strong>Tumeurs endocrines (ECL) :</strong> fundiques ;<br>\n              <strong>Carcinomes rares :</strong> adéno-squameux, épidermoïde, à petites cellules, indifférencié ;<br>\n              <strong>Métastases gastriques :</strong> rares — <span class=\"kw-clinique\">sein</span>, rein, poumon.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Repère pédagogique.</strong> <span class=\"kw-chiffre\">ADK = 95 %</span> — toute autre <span class=\"kw-bio\">histologie</span> doit être recherchée si le tableau est atypique (sujet jeune, <span class=\"kw-clinique\">masse</span> sous-muqueuse, <span class=\"kw-clinique\">ulcération</span> volumineuse non cicatrisante).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers</em></p>","frequence":1},{"id":"303-2","rang":"B","rubrique":"Epidémiologie","titre":"Epidémiologie descriptive : connaître l’incidence et la prévalence","contenu":"<table >\n        <thead>\n          <tr><th>Item</th><th>Données clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence mondiale</strong></td>\n            <td><span class=\"kw-chiffre\">5ème cancer</span> le plus fréquent dans le monde, <span class=\"kw-chiffre\">3ème cancer digestif</span> (après CCR et pancréas).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> mondiale</strong></td>\n            <td>En baisse (frigo, fruits/légumes, recul de <span class=\"kw-clinique\">HP</span>) ; <span class=\"kw-chiffre\">¾</span> des nouveaux cas surviennent en Asie, Amérique du Sud, Amérique centrale.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> selon le type</strong></td>\n            <td>Augmentation : cancers du <strong>cardia</strong> et de type <strong>diffus</strong> ;<br>Diminution : formes <strong>distales</strong> et de type <strong>intestinal</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>France</strong></td>\n            <td><span class=\"kw-chiffre\">6 500 nouveaux cas / an</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Sex-ratio</strong></td>\n            <td>Prédominance masculine — <span class=\"kw-chiffre\">2 H / 1 F</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Âge de survenue</strong></td>\n            <td>Âge moyen <span class=\"kw-chiffre\">70 ans</span> (H :<span class=\"kw-chiffre\"> 65-75 ans</span> ; F :<span class=\"kw-chiffre\"> 75-85 ans</span>) ; formes du sujet jeune possibles si prédisposition <span class=\"kw-etio\">génétique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span></strong></td>\n            <td>Survie à<span class=\"kw-chiffre\"> 5 ans</span> <span class=\"kw-alerte\">&lt; 30 %</span> (<span class=\"kw-chiffre\">15 %</span> tous stades ;<span class=\"kw-chiffre\"> 40 %</span> si localisé/opéré ;<span class=\"kw-chiffre\"> 12-16 mois</span> si M+). <span class=\"kw-def\">Mortalité</span> globale <span class=\"kw-chiffre\">en diminution</span> mais reste la <span class=\"kw-alerte\">2ème cause de mortalité par cancer dans le monde</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":0},{"id":"303-3","rang":"A","rubrique":"Étiologies","titre":"Epidémiologie analytique : connaître les facteurs de risque","contenu":"<table >\n        <thead>\n          <tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Alimentation</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Nitrites</span> :</strong> <span class=\"kw-alerte\">forte consommation</span> ;<br>\n              <strong><span class=\"kw-etio\">Sel</span> :</strong> <span class=\"kw-alerte\">consommation élevée</span> (composés <span class=\"kw-bio\">N-nitrosés</span> cancérigènes) ;<br>\n              <strong><span class=\"kw-etio\">Faible consommation de fruits & légumes</span></strong> (déficit en antioxydants).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mode de vie</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Tabagisme</span> :</strong> <span class=\"kw-alerte\">hydrocarbures cancérigènes</span> ;<br>\n              <strong><span class=\"kw-etio\">Surcharge pondérale</span> :</strong> <span class=\"kw-alerte\">ADK du cardia ++</span> ;<br>\n              <strong><span class=\"kw-etio\">Bas niveau socio-économique</span>.</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infection</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Helicobacter pylori</span> :</strong> responsable de <span class=\"kw-chiffre\">65-80 %</span> des ADK — peu impliqué dans le cardia, dégénérescence <span class=\"kw-chiffre\">&lt; 1 %</span> ;<br>\n              <strong><span class=\"kw-etio\">EBV</span> :</strong> rôle suspecté.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FdR héréditaires</strong> (~<span class=\"kw-chiffre\">3 %</span> ; prédisposition familiale dans <span class=\"kw-chiffre\">10 %</span>)</td>\n            <td>\n              <strong>Cancers gastriques diffus héréditaires :</strong> <span class=\"kw-bio\">CDH1</span>, autosomique dominant ;<br>\n              <strong><span class=\"kw-clinique\">Syndrome de Lynch</span> :</strong> <span class=\"kw-bio\">MMR</span> ;<br>\n              <strong>Polypose adénomateuse familiale :</strong> <span class=\"kw-bio\">APC</span> ;<br>\n              <strong>Apparentés au 1er degré</strong> d’un patient atteint ;<br>\n              <strong>Indication formelle de <span class=\"kw-clinique\">consultation d’oncogénétique</span></strong> dès suspicion (CDH1/Lynch/FAP, prédisposition familiale).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lésions précancéreuses</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Gastrite atrophique</span></strong> ;<br>\n              <strong><span class=\"kw-clinique\">Métaplasie intestinale</span></strong> ;<br>\n              <strong>Polypes adénomateux</strong> ;<br>\n              <strong>Ulcère gastrique</strong> ;<br>\n              <strong><span class=\"kw-clinique\">Gastrectomie partielle</span> :</strong> risque <span class=\"kw-chiffre\">10-15 ans</span> après (reflux digestif sur moignon) ;<br>\n              <strong>Maladie de Biermer</strong> ;<br>\n              <strong>Maladie de Ménétrier :</strong> dégénérescence <span class=\"kw-chiffre\">10 %</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Cancers gastriques diffus héréditaires (<span class=\"kw-bio\">CDH1</span>).</strong>\n        Mutation germinale du gène <span class=\"kw-bio\">CDH1</span> → perte de fonction de l’<span class=\"kw-bio\">E-cadhérine</span> (molécule d’adhésion).\n        Transmission <span class=\"kw-bio\">autosomique dominante</span>, à pénétrance variable.\n        <br><strong>Quand évoquer ?</strong>\n        <ul>\n          <li><span class=\"kw-chiffre\">≥ 2</span> cas de CG diffus chez apparentés 1er/2nd degré dont 1 cas <span class=\"kw-chiffre\">&lt; 50 ans</span> ;</li>\n          <li><span class=\"kw-chiffre\">≥ 3</span> cas de CG diffus chez apparentés 1er/2nd degré, tous âges ;</li>\n          <li>CG diffus diagnostiqué <span class=\"kw-chiffre\">&lt; 45 ans</span> ;</li>\n          <li>Association CG diffus + <span class=\"kw-clinique\">carcinome</span> lobulaire mammaire ou colorectal à cellules indépendantes chez un même individu ou 2 apparentés.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Rôle environnemental étayé.</strong> <span class=\"kw-clinique\">Les</span> cancers de l’estomac sont moins fréquents chez les descendants de Japonais émigrés aux États-Unis que chez les Japonais vivant dans leur pays d’origine.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 291 — Cancérogénèse - oncogénétique · 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":0},{"id":"303-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les grands principes de la carcinogenèse gastrique, connaître les lésions prédisposantes","contenu":"<p>La carcinogenèse gastrique est un <span class=\"kw-def\">processus multifactoriel</span> qui suit la <strong>séquence de Correa</strong> dans la forme intestinale (la plus fréquente). La forme diffuse (linite) suit une carcinogenèse moins bien comprise, hors prédisposition <span class=\"kw-bio\">CDH1</span>.</p>\n      <ol>\n        <li><strong><span class=\"kw-clinique\">Gastrite chronique</span> :</strong> inflammation chronique, principalement liée à <span class=\"kw-clinique\">Helicobacter pylori</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Atrophie gastrique</span> :</strong> perte des glandes gastriques → <span class=\"kw-bio\">hypochlorhydrie</span> → prolifération <span class=\"kw-etio\">bactérienne</span> → production de <span class=\"kw-bio\">nitrosamines</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Métaplasie intestinale</span> :</strong> remplacement de l’épithélium gastrique par un épithélium de type intestinal.</li>\n        <li><strong><span class=\"kw-clinique\">Dysplasie</span> :</strong> <span class=\"kw-clinique\">carcinome</span> intra-épithélial → <span class=\"kw-alerte\">carcinome invasif</span>.</li>\n      </ol>\n      <p>La transformation maligne dépend également de cofacteurs : <span class=\"kw-etio\">sel</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alimentation pauvre en antioxydants</span>. Pour la forme diffuse, la <span class=\"kw-def\">physiopathologie</span> reste largement inconnue en dehors des formes familiales liées à <span class=\"kw-bio\">CDH1</span>.</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Mécanisme prédisposant</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Gastrite atrophique</span></strong></td><td>Étape 2 de la séquence de Correa ; <span class=\"kw-bio\">hypochlorhydrie</span> → nitrosamines.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Métaplasie intestinale</span></strong></td><td>Étape 3 de la séquence de Correa.</td></tr>\n          <tr><td><strong>Polypes adénomateux</strong></td><td><span class=\"kw-clinique\">Lésion</span> précancéreuse classique (dysplasie possible).</td></tr>\n          <tr><td><strong>Ulcère gastrique chronique</strong></td><td>Inflammation chronique de berges.</td></tr>\n          <tr><td><strong>Maladie de Biermer</strong></td><td><span class=\"kw-clinique\">Gastrite</span> atrophique <span class=\"kw-etio\">auto-immune</span> + hypochlorhydrie.</td></tr>\n          <tr><td><strong>Maladie de Ménétrier</strong></td><td>Gastropathie hypertrophique — dégénérescence dans <span class=\"kw-chiffre\">10 %</span>.</td></tr>\n          <tr><td><strong>Moignon gastrique</strong></td><td>Post-gastrectomie partielle (reflux liq. digestif), risque à<span class=\"kw-chiffre\"> 10-15 ans</span>.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 291 — Cancérogénèse - oncogénétique · 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span></em></p>","frequence":1},{"id":"303-5","rang":"B","rubrique":"Prise en charge","titre":"Infection bactérienne : connaître les indications de la recherche d’HP","contenu":"<p><span class=\"kw-clinique\">Helicobacter pylori</span> est responsable de <span class=\"kw-chiffre\">65-80 %</span> des ADK gastriques distaux (peu impliqué dans le cardia) et constitue le facteur étiologique principal du <span class=\"kw-clinique\">lymphome gastrique de MALT à petites cellules</span>. Sa recherche s’intègre à la fois dans le diagnostic, la prévention et le <span class=\"kw-def\">suivi</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Indication de recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Bilan <span class=\"kw-imagerie\">EOGD</span> d’un cancer gastrique</strong></td><td>Recherche <span class=\"kw-bio\">systématique</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">biopsies</span> (test rapide à l’uréase + <span class=\"kw-bio\">histologie</span> ± culture/<span class=\"kw-bio\">PCR</span>).</td></tr>\n          <tr><td><strong>Dyspepsie d’apparition récente <span class=\"kw-chiffre\">&gt; 50 ans</span></strong></td><td>Signe d’alerte 🚩 — recherche au cours de l’<span class=\"kw-imagerie\">EOGD</span> diagnostique.</td></tr>\n          <tr><td><strong>Ulcère gastrique ou duodénal</strong></td><td>Recherche systématique avec éradication si positive.</td></tr>\n          <tr><td><strong>Lymphome gastrique de MALT</strong></td><td>Recherche systématique (éradication = traitement de <span class=\"kw-chiffre\">1ère ligne</span> des formes localisées).</td></tr>\n          <tr><td><strong>Apparentés au 1er degré d’un patient atteint de cancer gastrique</strong></td><td>Recherche orientée — éradication préventive si positive.</td></tr>\n          <tr><td><strong>Antécédent de gastrectomie partielle, atrophie gastrique, métaplasie intestinale</strong></td><td>Recherche dans le cadre du <span class=\"kw-def\">suivi</span> des lésions précancéreuses.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modalités diagnostiques.</strong> Tests <strong>directs</strong> : <span class=\"kw-bio\">biopsies</span> <span class=\"kw-imagerie\">EOGD</span> (<span class=\"kw-bio\">histologie</span> / culture / <span class=\"kw-bio\">PCR</span> / test rapide à l’uréase). Tests <strong>indirects</strong> : <span class=\"kw-bio\">test respiratoire à l’urée 13C</span>, antigènes dans <span class=\"kw-clinique\">les</span> selles, <span class=\"kw-bio\">sérologie</span> (utile en cas d’hémorragie digestive qui rend les <span class=\"kw-bio\">biopsies</span> prises en défaut).</p>\n      <div class=\"callout callout-info\">\n        <strong>Bénéfice clinique.</strong>\n        <ul>\n          <li><span class=\"kw-ttt\">Éradication → régression du lymphome de MALT dans <span class=\"kw-chiffre\">70 %</span></span> des formes localisées sans atteinte ganglionnaire ;</li>\n          <li>Prévention de la progression de la séquence de Correa (<span class=\"kw-clinique\">gastrite</span> → atrophie → métaplasie → dysplasie).</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span></em></p>","frequence":0},{"id":"303-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le type histologique le plus fréquent : adénocarcinome","contenu":"<p>L’<span class=\"kw-def\">adénocarcinome</span> représente <span class=\"kw-chiffre\">95 %</span> des tumeurs malignes gastriques. Il regroupe <strong>4 types histologiques</strong> : <strong>tubuleux</strong>, <strong>papillaire</strong>, <strong>mucineux</strong> (colloïde muqueux) et <strong>à cellules indépendantes</strong> (cellules en bague à chaton).</p>\n      <table >\n        <thead>\n          <tr><th>Type de Lauren</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Type intestinal glandulaire</strong></td>\n            <td>\n              <strong>Carcinogenèse :</strong> séquence de Correa sur <span class=\"kw-clinique\">gastrite</span> atrophique ;<br>\n              <strong>FdR principal :</strong> <span class=\"kw-clinique\">HP ++</span> ;<br>\n              <strong>Localisation :</strong> ADK distal préférentiel ;<br>\n              <strong>Aspect :</strong> tumeurs bourgeonnantes ou ulcéro-végétantes ;<br>\n              <strong><span class=\"kw-def\">Pronostic</span> :</strong> meilleur.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Type diffus à cellules indépendantes</strong> (en bague à chaton)</td>\n            <td>\n              <strong>Entité :</strong> <span class=\"kw-clinique\">linite gastrique</span> ;<br>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> sujet jeune, ± féminin ;<br>\n              <strong><span class=\"kw-etio\">Génétique</span> :</strong> lien <span class=\"kw-bio\">CDH1</span> dans <span class=\"kw-clinique\">les</span> formes familiales ;<br>\n              <strong>Carcinogenèse :</strong> processus moins connus ;<br>\n              <strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-alerte\">péjoratif</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead>\n          <tr><th>Topographie</th><th>Proportion</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Cardia</strong></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><strong>Grosse tubérosité</strong></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><strong>Corps</strong></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><strong>Antre</strong></td><td><span class=\"kw-chiffre\">40 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Classification</span> moléculaire.</strong> L’ADK gastrique est également classé selon des altérations moléculaires : <span class=\"kw-bio\">HER2</span> (positif dans <span class=\"kw-chiffre\">10-20 %</span> des formes métastatiques), <span class=\"kw-bio\">statut MSI</span>, expression de <span class=\"kw-bio\">PD-L1</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Dynamique épidémio des sous-types.</strong>\n        <strong>Cardia :</strong> <span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">stable voire en légère augmentation</span> — FdR principaux : <span class=\"kw-etio\">RGO</span>, <span class=\"kw-etio\">surcharge pondérale</span>.<br>\n        <strong>Estomac distal (antre-pylore) :</strong> incidence <span class=\"kw-chiffre\">en diminution</span> — FdR principal : <span class=\"kw-etio\">Helicobacter pylori</span> (corrélée au recul de la <span class=\"kw-def\">prévalence</span> d’HP en Occident).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 305 — Tumeur de l'œsophage</em></p>","frequence":0},{"id":"303-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les différents types histologiques et l’évolution naturelle du cancer gastrique","contenu":"<table >\n        <thead>\n          <tr><th>Autre tumeur maligne</th><th>Caractéristiques clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Lymphome de MALT à petites cellules</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Grade</span> :</strong> bas grade, <span class=\"kw-clinique\">évolution</span> très lente ;<br>\n              <strong>Étiologie :</strong> <span class=\"kw-etio\">infection chronique à Helicobacter pylori</span> ;<br>\n              <strong>Traitement :</strong> <span class=\"kw-ttt\">éradication HP → régression dans <span class=\"kw-chiffre\">70 %</span></span> des formes localisées.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lymphome à grandes cellules</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Grade</span> :</strong> haut grade ;<br>\n              <strong>Traitement :</strong> <span class=\"kw-ttt\">poly-chimiothérapie</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>GIST</strong> (tumeur mésenchymateuse rare)</td>\n            <td>\n              <strong>Origine :</strong> cellules de Cajal (<span class=\"kw-ttt\">pacemaker</span> digestif) ;<br>\n              <strong>Localisation :</strong> estomac dans <span class=\"kw-chiffre\">50 %</span> des cas ;<br>\n              <strong>Aspect :</strong> <span class=\"kw-clinique\">masse</span> ronde sous-muqueuse, parfois ulcérée ;<br>\n              <strong><span class=\"kw-bio\">IHC</span> :</strong> <span class=\"kw-bio\">c-kit (CD117)</span> ou <span class=\"kw-bio\">DOG1</span> ;<br>\n              <strong>Traitement :</strong> <span class=\"kw-ttt\">exérèse</span> monobloc ; <span class=\"kw-ttt\">imatinib</span> si non résécable.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tumeurs endocrines (ECL)</strong></td>\n            <td>\n              <strong>Contexte :</strong> hypergastrinémie secondaire (<span class=\"kw-clinique\">Biermer</span>) ou primaire (<span class=\"kw-clinique\">Zollinger-Ellison</span>) ;<br>\n              <strong>Aspect :</strong> multiples, petite taille ;<br>\n              <strong><span class=\"kw-bio\">Différenciation</span> / agressivité :</strong> reflétées par le <span class=\"kw-bio\">marquage Ki67</span> (index de prolifération) ;<br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> lente, métastases exceptionnelles.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Carcinomes rares</strong></td>\n            <td>Adéno-squameux, épidermoïde, à petites cellules, indifférencié.</td>\n          </tr>\n          <tr>\n            <td><strong>Métastases gastriques</strong> (rares)</td>\n            <td><span class=\"kw-clinique\">Sein</span> en 1er, rein, poumon.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Linite gastrique — anapath et poids épidémio.</strong>\n        <span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">ADK de forme diffuse</span> représentent environ <span class=\"kw-chiffre\">10 %</span> des cancers gastriques. Histologiquement, il s’agit d’un <span class=\"kw-def\">adénocarcinome peu différencié infiltrant</span> constitué de <span class=\"kw-bio\">cellules indépendantes en bague à chaton</span> baignant dans un <span class=\"kw-bio\">stroma fibreux</span>, envahissant les couches pariétales <strong>sans les détruire</strong> (muqueuse souvent saine en surface). D’où la nécessité de <span class=\"kw-imagerie\">biopsies en puits</span> profondes — les <span class=\"kw-bio\">biopsies</span> superficielles classiques sont fréquemment négatives.\n      </div>\n      <table >\n        <thead>\n          <tr><th>Étape évolutive</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Extension locale</strong></td>\n            <td>Atteinte pariétale en profondeur, puis péritoine en 1er → pancréas, foie, diaphragme.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Envahissement</span> ganglionnaire</strong> (précoce)</td>\n            <td><span class=\"kw-chiffre\">60-80 %</span> au diagnostic — pér<span class=\"kw-chiffre\">iga</span>striques proximaux &gt; pédiculaire &gt; périgastriques distaux.</td>\n          </tr>\n          <tr>\n            <td><strong>Métastases viscérales</strong></td>\n            <td>\n              <strong>4 principaux :</strong> <span class=\"kw-alerte\">foie, péritoine, poumons, os</span> ;<br>\n              <strong>3 rares :</strong> <span class=\"kw-clinique\">Krukenberg ovaire</span>, thyroïde, peau.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Tumeur de Krukenberg.</strong> Métastase ovarienne <span class=\"kw-alerte\">bilatérale</span> à cellules indépendantes — drapeau oncologique classique chez la femme. Imposer la recherche d’un primitif gastrique devant toute <span class=\"kw-clinique\">masse</span> ovarienne d’allure métastatique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 276 — <span class=\"kw-clinique\">Hépatomégalie</span> - <span class=\"kw-clinique\">masse</span> abdominale · 304 — Tumeur du foie · 301 — Tumeur colon - rectum · 305 — Tumeur de l'œsophage · 308 — Tumeur pancréas</em></p>","frequence":0},{"id":"303-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances de découverte","contenu":"<p><span class=\"kw-clinique\">Les</span> tumeurs gastriques sont le plus souvent <strong>asymptomatiques</strong> au <span class=\"kw-def\">stade</span> initial. La découverte se fait soit sur signes d’alerte, soit fortuitement (<span class=\"kw-def\">dépistage</span>, bilan d’anémie), soit sur complication révélatrice.</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Signes d’alerte (annale) 🚩</strong></td>\n            <td>\n              <strong>Dyspepsie d’apparition récente</strong> qui s’accentue, surtout <span class=\"kw-chiffre\">&gt; 50 ans ++</span> ;<br>\n              <strong>Crampes ép<span class=\"kw-chiffre\">iga</span>striques post-prandiales</strong> sans périodicité ulcéreuse classique.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes généraux</strong></td>\n            <td><span class=\"kw-clinique\">Perte de poids</span>, <span class=\"kw-clinique\">anorexie</span> avec <span class=\"kw-clinique\">dégoût des viandes</span>, <span class=\"kw-clinique\">asthénie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes locaux selon topographie</strong></td>\n            <td>\n              <strong>Cardia (<span class=\"kw-chiffre\">40 %</span>) :</strong> <span class=\"kw-clinique\">dysphagie progressive</span>, <span class=\"kw-clinique\">régurgitations</span>, douleurs rétrosternales, hoquet ;<br>\n              <strong>Corps (<span class=\"kw-chiffre\">20 %</span>) :</strong> douleur ép<span class=\"kw-chiffre\">iga</span>strique pseudo-ulcéreuse, le plus souvent peu symptomatique ;<br>\n              <strong>Antre-pylore (<span class=\"kw-chiffre\">40 %</span>) :</strong> syndrome occlusif haut (<span class=\"kw-clinique\">vomissements alimentaires sans bile</span>, pas de niveaux hydro-aériques), <span class=\"kw-clinique\">tuméfaction</span> de l’hypochondre gauche, <span class=\"kw-clinique\">clapotage à jeun</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Découverte indirecte</strong></td>\n            <td>Bilan d’<span class=\"kw-bio\">anémie ferriprive</span> isolée (homme âgé +++) ; <span class=\"kw-def\">dépistage</span> des sujets à risque.</td>\n          </tr>\n          <tr>\n            <td><strong>Complications révélatrices</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Péritonite</span> :</strong> perforation libre ou cloisonnée ;<br>\n              <strong><span class=\"kw-alerte\">Hémorragie digestive</span> :</strong> anémie hypochrome, <span class=\"kw-clinique\">hématémèse</span>, <span class=\"kw-clinique\">méléna</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’extension</strong></td>\n            <td>\n              <strong>Ganglion de Troisier :</strong> <span class=\"kw-clinique\">adénopathie</span> sus-claviculaire gauche (classique mais rare) ;<br>\n              <strong><span class=\"kw-clinique\">Hépatomégalie</span> :</strong> foie marronné métastatique ;<br>\n              <strong><span class=\"kw-clinique\">Ascite</span></strong> <span class=\"kw-etio\">néoplasique</span> ;<br>\n              <strong><span class=\"kw-clinique\">Nodule</span> de Douglas :</strong> carcinose péritonéale perçue au TR ;<br>\n              <strong>Tumeur de Krukenberg :</strong> métastase ovarienne.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Syndromes paranéoplasiques</strong> (rares)</td>\n            <td>\n              <strong>Cutané :</strong> <span class=\"kw-clinique\">acanthosis nigricans</span> (plaques hyperp<span class=\"kw-chiffre\">igm</span>entées : nez, axillaires, ano-génital), syndromes ichtyosiformes ;<br>\n              <strong>Hématologique :</strong> <span class=\"kw-clinique\">phlébite de Trousseau</span> (<span class=\"kw-def\">TVP</span> des membres) ;<br>\n              <strong>Digestif :</strong> <span class=\"kw-clinique\">diarrhée</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 273 — <span class=\"kw-clinique\">Dysphagie</span> · 274 — <span class=\"kw-clinique\">Vomissements</span> · 276 — <span class=\"kw-clinique\">Hépatomégalie</span> - <span class=\"kw-clinique\">masse</span> abdominale · 292 — Diagnostic des cancers</em></p>","frequence":1},{"id":"303-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les différentes étapes de l’examen clinique","contenu":"<table >\n        <thead>\n          <tr><th>Étape</th><th>Éléments à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire ciblé</strong></td>\n            <td>\n              <strong>Signes d’alerte :</strong> dyspepsie récente, crampes ép<span class=\"kw-chiffre\">iga</span>striques, <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">perte de poids</span>, dégoût des viandes ;<br>\n              <strong>ATCD personnels :</strong> <span class=\"kw-clinique\">RGO</span>, ulcère, gastrectomie partielle, <span class=\"kw-clinique\">Biermer</span>, Ménétrier ;<br>\n              <strong>ATCD familiaux :</strong> cancers digestifs, sein lobulaire, Lynch, FAP ;<br>\n              <strong>FdR :</strong> <span class=\"kw-clinique\">HP</span>, <span class=\"kw-etio\">tabac</span>, alimentation salée, surcharge pondérale.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen général</strong></td>\n            <td>Poids, taille, IMC, % d’<span class=\"kw-clinique\">amaigrissement</span>, état nutritionnel, <span class=\"kw-clinique\">performance status</span> (OMS / ECOG).</td>\n          </tr>\n          <tr>\n            <td><strong>Examen abdominal</strong></td>\n            <td>\n              <strong>Palpation :</strong> <span class=\"kw-clinique\">tuméfaction de l’hypochondre gauche</span>, <span class=\"kw-clinique\">hépatomégalie</span> marronnée ;<br>\n              <strong>Percussion :</strong> matité d’<span class=\"kw-clinique\">ascite</span> ;<br>\n              <strong>Manœuvre :</strong> <span class=\"kw-clinique\">clapotage à jeun</span> par mobilisation abdominale.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Aires ganglionnaires</strong></td>\n            <td>Recherche du <span class=\"kw-clinique\">ganglion de Troisier</span> (sus-claviculaire gauche), aires périphériques.</td>\n          </tr>\n          <tr>\n            <td><strong>Toucher rectal</strong></td>\n            <td><span class=\"kw-clinique\">Nodule</span> de carcinose dans le <span class=\"kw-clinique\">cul-de-sac de Douglas</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Examen gynécologique</strong> (femme)</td>\n            <td>Recherche d’une <span class=\"kw-clinique\">tumeur de Krukenberg</span> ovarienne.</td>\n          </tr>\n          <tr>\n            <td><strong>Examen cutané</strong></td>\n            <td><span class=\"kw-clinique\">Acanthosis nigricans</span> (nez, aires axillaires, région ano-génitale), ichtyose <span class=\"kw-etio\">paranéoplasique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Examen vasculaire</strong></td>\n            <td>Recherche d’une <span class=\"kw-def\">TVP</span> — <span class=\"kw-clinique\">phlébite de Trousseau</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 276 — <span class=\"kw-clinique\">Hépatomégalie</span> - <span class=\"kw-clinique\">masse</span> abdominale</em></p>","frequence":0},{"id":"303-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le bilan biologique","contenu":"<p><span class=\"kw-alerte\">Aucun bilan biologique n’est utile au diagnostic positif</span> du cancer de l’estomac (qui repose sur l’<span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-bio\">biopsies</span>). La biologie sert exclusivement à <strong>évaluer le retentissement</strong>, à préparer la PEC et à suivre l’efficacité thérapeutique en situation métastatique.</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Objectif / interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Hémogramme</span> (<span class=\"kw-bio\">NFS</span>)</strong></td>\n            <td>Recherche d’<span class=\"kw-bio\">anémie ferriprive</span> (hypochrome, microcytaire, <span class=\"kw-bio\">ferritine basse</span>) — fréquente, parfois révélatrice ; thrombopénie d’<span class=\"kw-bio\">envahissement</span> médullaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan nutritionnel</strong></td>\n            <td><span class=\"kw-bio\">Albuminémie</span>, <span class=\"kw-bio\">préalbumine</span>, % d’<span class=\"kw-clinique\">amaigrissement</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Ionogramme</span> + <span class=\"kw-bio\">créatininémie</span></strong></td>\n            <td>Retentissement des <span class=\"kw-clinique\">vomissements</span> (alcalose hypokaliémique sur sténose pylorique) ; évaluation rénale avant <span class=\"kw-ttt\">chimiothérapie</span> néphrotoxique.</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan hépatique</strong></td>\n            <td>Orientation vers des métastases hépatiques (cytolyse, <span class=\"kw-clinique\">cholestase</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Calcémie</span></strong></td>\n            <td>Recherche d’une hypercalcémie <span class=\"kw-etio\">paranéoplasique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Hémostase (<span class=\"kw-bio\">TP</span>-<span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">plaquettes</span>)</strong></td>\n            <td>Préalable aux <span class=\"kw-bio\">biopsies</span> endoscopiques.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Marqueurs tumoraux.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Aucun marqueur tumoral n’est indiqué pour le diagnostic ou l’évaluation pronostique</span> du cancer gastrique.</li>\n          <li><span class=\"kw-bio\">ACE</span> et <span class=\"kw-bio\">CA 19-9</span> : intérêt limité au <strong><span class=\"kw-def\">suivi</span> de l’efficacité du traitement en situation métastatique</strong>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0},{"id":"303-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens endoscopiques et paracliniques","contenu":"<table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">EOGD</span> avec <span class=\"kw-bio\">biopsies</span></strong> (examen clé)</td>\n            <td>\n              <strong>Rendement :</strong> <span class=\"kw-imagerie\">diagnostic dans 95 % des cas</span> ;<br>\n              <strong><span class=\"kw-bio\">Biopsies</span> :</strong> <span class=\"kw-chiffre\">≥ 5 à 8</span>, profondes, sur la <span class=\"kw-clinique\">lésion</span> et à distance ;<br>\n              <strong>Recherche associée :</strong> <span class=\"kw-bio\">HP systématique</span> sur <span class=\"kw-bio\">biopsies</span> ;<br>\n              <strong>Description :</strong> topographie, aspect (ulcéreux, végétant, ulcéro-végétant), signes de malignité (caractère <span class=\"kw-imagerie\">irrégulier</span>, <span class=\"kw-imagerie\">saignement spontané ou au contact</span>, rigidité).\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoraco-abdomino-pelvienne (TAP)</strong></td>\n            <td><span class=\"kw-imagerie\">Examen indispensable</span> — au mieux avec ingestion d’eau pour préciser l’extension pariétale ; bilan de résécabilité + recherche de métastases (foie, poumon, ganglions, péritoine).</td>\n          </tr>\n          <tr>\n            <td><strong>Écho-<span class=\"kw-imagerie\">endoscopie</span></strong> (non systématique)</td>\n            <td>\n              Indications :<br>\n              <strong>Suspicion de linite :</strong> évaluation de l’extension sur œsophage / pylore / duodénum + repérage d’un <span class=\"kw-imagerie\">épaississement pariétal prédominant à la sous-muqueuse</span> (signe orientant) ;<br>\n              <strong>Petite tumeur :</strong> caractère superficiel pour mucosectomie ;<br>\n              <strong>Allure sous-muqueuse :</strong> diagnostic de GIST.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cœlioscopie diagnostique</strong></td>\n            <td>Recherche de <span class=\"kw-clinique\">carcinose péritonéale</span> infraradiologique — peut éviter une laparotomie inutile dans <span class=\"kw-chiffre\">jusqu’à 38 %</span> des cas.</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan <span class=\"kw-bio\">IHC</span> / moléculaire</strong></td>\n            <td><span class=\"kw-bio\">HER2</span> systématique si métastatique (positif dans <span class=\"kw-chiffre\">10-20 %</span>) → indication de <span class=\"kw-ttt\">trastuzumab</span> en <span class=\"kw-chiffre\">1ère ligne</span> ; <span class=\"kw-bio\">FISH</span> de confirmation si <span class=\"kw-bio\">IHC</span> ++.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP</span>-<span class=\"kw-imagerie\">TDM</span></strong></td>\n            <td>Non systématique — discuté au cas par cas.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> cérébrale / <span class=\"kw-imagerie\">scintigraphie</span> osseuse</strong></td>\n            <td>Sur point d’appel clinique uniquement.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique de la linite plastique.</strong> <span class=\"kw-alerte\">Les biopsies superficielles peuvent être négatives</span> en cas de linite — réaliser des <strong><span class=\"kw-bio\">biopsies</span> en puits</strong>, compléter par une écho-<span class=\"kw-imagerie\">endoscopie</span>, et <span class=\"kw-ci\">ne jamais</span> éliminer le diagnostic si la paroi reste rigide à l’<span class=\"kw-imagerie\">EOGD</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 273 — <span class=\"kw-clinique\">Dysphagie</span></em></p>","frequence":0},{"id":"303-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les diagnostics différentiels","contenu":"<table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Démarche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Ulcère gastrique</span></strong></td>\n            <td>La découverte de <span class=\"kw-bio\">cellules malignes</span> affirme le cancer ; leur <span class=\"kw-alerte\">absence n’autorise pas à éliminer le diagnostic</span> → <span class=\"kw-def\">suivi</span> endoscopique systématique avec <span class=\"kw-imagerie\">biopsies itératives</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeur gastrique bénigne</strong></td>\n            <td>Révélation par <span class=\"kw-clinique\">douleurs épigastriques atypiques</span> ou <span class=\"kw-clinique\">hémorragie digestive</span> ; la <span class=\"kw-imagerie\">fibroscopie</span> objective la tumeur mais ne préjuge pas de sa nature → <span class=\"kw-bio\">anatomopathologie</span> sur pièce d’<span class=\"kw-ttt\">exérèse</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Envahissement</span> gastrique de contiguïté</strong></td>\n            <td>Origine <span class=\"kw-clinique\">pancréatique</span> ou <span class=\"kw-clinique\">colique transverse</span> → <span class=\"kw-imagerie\">TDM AP</span> + <span class=\"kw-imagerie\">coloscopie</span> pour identifier la <span class=\"kw-clinique\">lésion</span> primitive ; <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">biopsies</span> confirment la nature.</td>\n          </tr>\n          <tr>\n            <td><strong>Bézoards / corps étrangers</strong></td>\n            <td>Diagnostic par <span class=\"kw-imagerie\">endoscopie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Gastrite chronique sévère</span> / <span class=\"kw-clinique\">maladie de Ménétrier</span></strong></td>\n            <td>Aspect endoscopique pseudo-<span class=\"kw-etio\">tumoral</span> (<span class=\"kw-imagerie\">gros plis hypertrophiques</span>) — <span class=\"kw-bio\">biopsies</span> discriminantes.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":0},{"id":"303-13","rang":"B","rubrique":"Contenu multimédia","titre":"Vidéo d’une gastroscopie avec réalisation de biopsies","contenu":"<p>La <strong><span class=\"kw-imagerie\">gastroscopie</span> (<span class=\"kw-imagerie\">EOGD</span>) avec <span class=\"kw-bio\">biopsies</span></strong> est l’examen clé du diagnostic — elle permet le diagnostic dans <span class=\"kw-chiffre\">95 %</span> des cas. Voici la sémiologie pratique de la procédure.</p>\n      <!-- TODO Kevin : ajouter vidéo .mp4 ou GIF de la procédure -->\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Préparation du patient</strong></td>\n            <td>Jeûne <span class=\"kw-chiffre\">≥ 6 h</span> ; décubitus latéral gauche ; sédation consciente (<span class=\"kw-ttt\">midazolam</span> IV) ± anesthésie locale du pharynx (xylocaïne spray) ; monitoring SpO₂.</td>\n          </tr>\n          <tr>\n            <td><strong>Procédure</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Intubation</span> œso-gastrique sous contrôle visuel, exploration systématique en aller-retour :<br>\n              <span class=\"kw-imagerie\">cardia → fundus (rétrovision)</span> → corps → angle de la petite courbure → antre → pylore → bulbe duodénal → D2 ;<br>\n              insufflation et désufflation pour évaluer la souplesse pariétale.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Repérage des anomalies</strong></td>\n            <td>\n              Signes très évocateurs de malignité :<br>\n              <strong><span class=\"kw-imagerie\">Caractère irrégulier</span></strong> de la muqueuse ;<br>\n              <strong><span class=\"kw-imagerie\">Saignement spontané ou au contact</span></strong> ;<br>\n              <strong><span class=\"kw-imagerie\">Paroi rigide</span></strong> à l’insufflation (drapeau pour la linite).\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Biopsies</span></strong></td>\n            <td>\n              <span class=\"kw-chiffre\">≥ 5 à 8</span> prélèvements, profonds (atteindre la sous-muqueuse), dirigés sur l’anomalie principale et à distance ;<br>\n              <span class=\"kw-bio\">prélèvement systématique pour recherche d’<i>Helicobacter pylori</i></span> (test rapide à l’uréase + <span class=\"kw-bio\">histologie</span> + culture/<span class=\"kw-bio\">PCR</span> si besoin).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pièges techniques</strong></td>\n            <td>\n              <strong>Linite gastrique :</strong> <span class=\"kw-bio\">biopsies</span> superficielles souvent négatives → <span class=\"kw-bio\">biopsies</span> <span class=\"kw-imagerie\">en puits</span> + écho-<span class=\"kw-imagerie\">endoscopie</span> ;<br>\n              <strong>Adénocarcinome superficiel :</strong> aspect d’ulcère superficiel ± étendu, biopsier toute anomalie même discrète ;<br>\n              <strong>Examen négatif malgré forte suspicion clinique :</strong> doit être recommencé.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Principe pratique.</strong> En pratique, <em>tout aspect anormal de la muqueuse doit être biopsié</em> — la rentabilité du geste dépend du nombre et de la profondeur des prélèvements.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/gastric-adenocarcinoma","label":"Radiopaedia : Gastric adenocarcinoma"},{"href":"https://radiopaedia.org/articles/linitis-plastica","label":"Radiopaedia : Linitis plastica"},{"href":"https://radiopaedia.org/articles/gastric-lymphoma","label":"Radiopaedia : Gastric lymphoma"},{"href":"https://radiopaedia.org/articles/gastrointestinal-stromal-tumor-2?lang=us","label":"Radiopaedia : Gastrointestinal stromal tumor 2"}]}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://fr.wikipedia.org/wiki/Acanthosis_nigricans","label":"Wikipedia — Acanthosis nigricans"}],"cards":[{"i":"123a8c814bc1","n":303,"o":"303-1","u":"Définition","t":"Connaître la définition des tumeurs de l’estomac","q":"Quel est le type histologique le plus fréquent des tumeurs malignes de l'estomac et quel est son pourcentage représentatif ?","a":"<p>L'<strong>adénocarcinome gastrique</strong> est le type histologique le plus fréquent, représentant à lui seul <strong>95 %</strong> des tumeurs malignes de l'estomac.</p>"},{"i":"8cb60bd00ecc","n":303,"o":"303-1","u":"Définition","t":"Connaître la définition des tumeurs de l’estomac","q":"Quels sont les différents types de tumeurs bénignes de l'estomac mentionnés ?","a":"<ul><li>Le <strong>polype hyperplasique</strong>, souvent localisé à l'antre.</li><li>Le <strong>polype glandulokystique</strong>, situé au fundus et associé aux IPP au long cours.</li><li>Le <strong>polype adénomateux</strong>, considéré comme une lésion précancéreuse.</li><li>La <strong>gastrite à gros plis de Ménétrier</strong>, qui est une entité exceptionnelle.</li></ul>"},{"i":"bd875ccbbf90","n":303,"o":"303-1","u":"Définition","t":"Connaître la définition des tumeurs de l’estomac","q":"Outre l'adénocarcinome, quelles autres tumeurs malignes de l'estomac doit-on avoir à l'esprit, notamment si le tableau clinique est atypique ?","a":"<ul><li>Le <strong>lymphome de MALT</strong> (à petites cellules, de bas grade, lié à <em>Helicobacter pylori</em>).</li><li>Le <strong>lymphome à grandes cellules</strong> (de haut grade).</li><li>Les <strong>GIST</strong> (tumeurs du stroma gastro-intestinales), qui sont des tumeurs mésenchymateuses des cellules de Cajal.</li><li>Les <strong>tumeurs endocrines</strong> (ECL), principalement fundiques.</li><li>Les <strong>carcinomes rares</strong> (adéno-squameux, épidermoïde, à petites cellules, indifférencié).</li><li>Les <strong>métastases gastriques</strong>, rares, provenant par exemple du sein, du rein ou du poumon.</li></ul>"},{"i":"d1255db5e7d2","n":303,"o":"303-1","u":"Définition","t":"Connaître la définition des tumeurs de l’estomac","q":"Quelle est la définition générale des tumeurs de l'estomac ?","a":"<p>Les tumeurs de l'estomac sont l'ensemble des <strong>proliférations cellulaires</strong>, qu'elles soient bénignes ou malignes, qui se développent à partir de la paroi gastrique.</p>"},{"i":"572f472dc810","n":303,"o":"303-10","u":"Diagnostic positif","t":"Connaître le bilan biologique","q":"Dans quel contexte et quels paramètres de l'hémogramme sont recherchés dans le cadre d'un cancer de l'estomac ?","a":"<p>L'hémogramme (NFS) est utile pour évaluer le retentissement du cancer de l'estomac. Il permet de rechercher :</p><ul><li>Une <strong>anémie ferriprive</strong> (hypochrome, microcytaire, ferritine basse), souvent révélatrice.</li><li>Une <strong>thrombopénie</strong> en cas d'envahissement médullaire.</li></ul>"},{"i":"5ff929010332","n":303,"o":"303-10","u":"Diagnostic positif","t":"Connaître le bilan biologique","q":"Comment les marqueurs tumoraux sont-ils utilisés dans la prise en charge du cancer de l'estomac selon l'EDN ?","a":"<p>Aucun marqueur tumoral n'est indiqué pour le diagnostic ou l'évaluation pronostique du cancer gastrique. L'<strong>ACE</strong> et le <strong>CA 19-9</strong> ont un intérêt <strong>limité au suivi de l'efficacité du traitement en situation métastatique</strong>.</p>"},{"i":"631d20e61877","n":303,"o":"303-10","u":"Diagnostic positif","t":"Connaître le bilan biologique","q":"Quels paramètres du bilan biologique permettent d'évaluer le retentissement nutritionnel et les conséquences des vomissements dans un cancer de l'estomac ?","a":"<p>Pour évaluer le retentissement nutritionnel :</p><ul><li><strong>Albuminémie</strong> et <strong>préalbumine</strong>.</li><li>Pour les conséquences des vomissements : l'<strong>ionogramme sanguin</strong> et la <strong>créatininémie</strong> peuvent révéler une alcalose hypokaliémique en cas de sténose pylorique et évaluer la fonction rénale avant chimiothérapie néphrotoxique.</p></ul>"},{"i":"802f29b972d2","n":303,"o":"303-10","u":"Diagnostic positif","t":"Connaître le bilan biologique","q":"Quelle est l'utilité du bilan biologique dans le diagnostic positif du cancer de l'estomac ?","a":"<p>Aucun bilan biologique n'est utile au diagnostic positif du cancer de l'estomac. Le diagnostic repose sur l'<strong>EOGD avec biopsies</strong>.</p>"},{"i":"fada34ced9f8","n":303,"o":"303-10","u":"Diagnostic positif","t":"Connaître le bilan biologique","q":"Quels sont les paramètres du bilan biologique qui orientent vers une éventuelle atteinte hépatique dans le contexte d'un cancer de l'estomac ?","a":"<p>Le <strong>bilan hépatique</strong> (cytolyse, cholestase) peut orienter vers des <strong>métastases hépatiques</strong>, même s'il n'est pas utilisé pour le diagnostic initial.</p>"},{"i":"050ec284fd29","n":303,"o":"303-3","u":"Étiologies","t":"Epidémiologie analytique : connaître les facteurs de risque","q":"Quels sont les principaux facteurs de risque alimentaires et liés au mode de vie des tumeurs de l'estomac ?","a":"<p>Les principaux facteurs de risque sont :</p><ul><li><strong>Alimentation :</strong> forte consommation de <strong>nitrites</strong> et de <strong>sel</strong> (composés N-nitrosés cancérigènes), faible consommation de <strong>fruits et légumes</strong>.</li><li><strong>Mode de vie :</strong> <strong>tabagisme</strong>, <strong>surcharge pondérale</strong> (particulièrement pour l'adénocarcinome du cardia), et bas niveau socio-économique.</li></ul>"},{"i":"549b387dc476","n":303,"o":"303-3","u":"Étiologies","t":"Epidémiologie analytique : connaître les facteurs de risque","q":"Quelles sont les principales lésions précancéreuses gastriques et les pathologies associées aux tumeurs de l'estomac ?","a":"<p>Les principales lésions précancéreuses sont :</p><ul><li>La <strong>gastrite atrophique</strong>.</li><li>La <strong>métaplasie intestinale</strong>.</li><li>Les <strong>polypes adénomateux</strong>.</li><li>L'<strong>ulcère gastrique</strong> (mais le rôle est plus celui de gastrite chronique associée).</li><li>La <strong>gastrectomie partielle</strong> (risque 10-15 ans après, en lien avec le reflux digestif sur le moignon).</li><li>La <strong>maladie de Biermer</strong>.</li><li>La <strong>maladie de Ménétrier</strong> (avec un risque de dégénérescence de 10 %).</li></ul>"},{"i":"7f6b76ebbaec","n":303,"o":"303-3","u":"Étiologies","t":"Epidémiologie analytique : connaître les facteurs de risque","q":"Quelle est la part de l'infection par <i>Helicobacter pylori</i> et du virus d'Epstein-Barr (EBV) dans l'étiologie des adénocarcinomes gastriques ?","a":"<ul><li><strong><i>Helicobacter pylori</i> :</strong> est responsable de <strong>65 à 80 %</strong> des adénocarcinomes gastriques, bien que peu impliqué dans les tumeurs du cardia. Le risque de dégénérescence est toutefois &lt; 1 %.</li><li><strong>EBV :</strong> un rôle est <strong>suspecté</strong> dans certains cancers de l'estomac.</li></ul>"},{"i":"bfc92b7dc2c0","n":303,"o":"303-3","u":"Étiologies","t":"Epidémiologie analytique : connaître les facteurs de risque","q":"Quelles sont les prédispositions héréditaires aux cancers gastriques, notamment pour les cancers gastriques diffus ?","a":"<p>Les prédispositions héréditaires représentent environ <strong>3 %</strong> des cas (et 10 % de prédisposition familiale) :</p><ul><li>Les <strong>cancers gastriques diffus héréditaires</strong>, liés à la mutation germinale du gène <strong>CDH1</strong> (autosomique dominant), entraînant une perte de fonction de l'E-cadhérine.</li><li>Le <strong>syndrome de Lynch</strong> (défauts des gènes MMR).</li><li>La <strong>polypose adénomateuse familiale</strong> (mutation du gène APC).</li><li>La présence d'<strong>apparentés au 1er degré</strong> atteints.</li></ul><p>Une consultation d'oncogénétique est formellement indiquée en cas de suspicion.</p>"},{"i":"e0fb5a29004f","n":303,"o":"303-3","u":"Étiologies","t":"Epidémiologie analytique : connaître les facteurs de risque","q":"Dans quelles situations doit-on évoquer un cancer gastrique diffus héréditaire lié au gène CDH1 ?","a":"<p>Un cancer gastrique diffus héréditaire doit être évoqué en présence des critères suivants :</p><ul><li><strong>≥ 2 cas</strong> de CG diffus chez des apparentés de 1er ou 2nd degré, dont <strong>1 cas < 50 ans</strong>.</li><li><strong>≥ 3 cas</strong> de CG diffus chez des apparentés de 1er ou 2nd degré, tous âges confondus.</li><li>Un CG diffus diagnostiqué <strong>< 45 ans</strong>.</li><li>L'association d'un CG diffus avec un <strong>carcinome lobulaire mammaire</strong> ou un cancer colorectal à cellules indépendantes chez le même individu ou chez deux apparentés.</li></ul>"},{"i":"20b31148dd9f","n":303,"o":"303-9","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les signes d'alerte et les antécédents à rechercher spécifiquement lors de l'interrogatoire d'un patient suspect de tumeur de l'estomac ?","a":"<p>Les <strong>signes d'alerte</strong> à rechercher sont une dyspepsie récente, des crampes épigastriques, un syndrome d'altération de l'état général (AEG), une perte de poids inexpliquée et un dégoût pour les viandes.</p><p>Les <strong>antécédents personnels</strong> pertinents incluent un RGO, un ulcère gastroduodénal, une gastrectomie partielle, la maladie de Biermer et la maladie de Ménétrier.</p><p>Les <strong>antécédents familiaux</strong> à considérer sont les cancers digestifs, le cancer du sein lobulaire, le syndrome de Lynch et la Polyadénomatose Familiale.</p>"},{"i":"df4cd1f6b7f6","n":303,"o":"303-9","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les éléments clés à évaluer lors de l'examen général et de l'examen abdominal chez un patient suspect de tumeur de l'estomac ?","a":"<p>Lors de l'<strong>examen général</strong>, il faut évaluer le poids, la taille, l'IMC, le pourcentage d'amaigrissement, l'état nutritionnel et le performance status (selon les scores OMS / ECOG).</p><p>À l'<strong>examen abdominal</strong>, la palpation peut révéler une tuméfaction de l'hypochondre gauche ou une hépatomégalie marronnée. La percussion peut montrer une matité d'ascite. La manœuvre de mobilisation abdominale peut mettre en évidence un clapotage à jeun.</p>"},{"i":"fe3ff16dcebf","n":303,"o":"303-9","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les points de recherche spécifiques lors de l'examen des aires ganglionnaires, du toucher rectal, de l'examen gynécologique et de l'examen cutané chez un patient suspect de tumeur de l'estomac ?","a":"<p>Au niveau des <strong>aires ganglionnaires</strong>, il faut rechercher le ganglion de Troisier (sus-claviculaire gauche) et explorer les aires périphériques.</p><p>Le <strong>toucher rectal</strong> peut révéler un nodule de carcinose dans le cul-de-sac de Douglas.</p><p>L'<strong>examen gynécologique</strong> (chez la femme) recherche une tumeur de Krukenberg ovarienne.</p><p>L'<strong>examen cutané</strong> peut montrer un acanthosis nigricans (nez, aires axillaires, région ano-génitale) ou une ichtyose paranéoplasique.</p>"}]};